exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', 'left join sysunit b on a.unit_id = b.unit_id left join dmkhupho d on a.ma_khupho = d.ma_khupho and a.ma_phuongxa = d.ma_phuongxa left join dmphuongxa e on a.ma_phuongxa = e.ma_phuongxa left join dmttp f on a.ma_ttp = f.ma_ttp', 'b.ma_unit, d.ten_khupho, e.ten_phuongxa, f.ten_ttp', '@@key', '', @@filterKey, '', @pageIndex, 50, @@admin, @@userId
